    JsonObject get(JsonObject p){FlowPlans.keys(p,"resultId");return store.read(c->{JsonObject value=Store.document(c,"input_results",FlowPlans.string(p,"resultId",128));Json.object(value,"provenance").remove("modelPath");Json.object(Json.object(value,"provenance"),"parameters").remove("imagePath");int bytes=value.toString().getBytes(StandardCharsets.UTF_8).length;if(bytes>MAX_RESULT_BYTES)throw new ApiError(413,"input_result_too_large","结果详情超过 32 MiB，完整原始与回映结果已不可变保存在数据库中。",Json.obj("resultId",value.get("id"),"stored",true,"serializedBytes",bytes,"requiresGeometryReview",true));return value;});}
