        JsonObject result=Json.obj("id",Json.id(),"runId",run.get("id"),"sampleId",sample.get("id"),"inputId",RunInputs.inputId(sample),"assetId",sample.get("assetId"),"source",source,"status",status,"createdAt",Json.now(),"annotations",annotations,"rawResult",raw,"mappedResult",mapping,"geometryIssues",issues,"requiresGeometryReview",!status.equals("succeeded"),"provenance",provenance==null?new JsonObject():provenance);if(attempt!=null)result.addProperty("attemptId",attempt);if(code!=null){result.addProperty("errorCode",code);result.addProperty("message",message);}
